<script src="https://cdnjs.cloudflare.com/ajax/libs/echarts/5.4.3/echarts.min.js"></script>
<script>
'use strict';
const PLAT='Facebook',API_BASE='/mk/api/facebook';
const OVCfg={pid:OV_PID,sd:OV_SD,ed:OV_ED,primary:'#038047',colors:{like:'#038047',share:'#06B6D4',comment:'#F59E0B',hashtag:'#038047'},perPage:10};
const DONUT_COLORS=['#038047','#273B4A','#F59E0B','#06B6D4','#EF4444'];
const TAB_TYPES=['hashtag','like','share','comment'];
const _$=id=>document.getElementById(id);const numF=n=>parseInt(n||0).toLocaleString('id-ID');const numK=n=>{n=parseInt(n||0);return n>=1e6?(n/1e6).toFixed(1)+'M':n>=1000?(n/1000).toFixed(1)+'k':String(n)};const esc=s=>(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');const dec=s=>{if(!s)return '';try{const f=decodeURIComponent(escape(s));if(!f.includes('\uFFFD')&&f!==s)return f}catch(e){}return s};const hideLd=id=>{const e=_$(id);if(e&&e.classList.contains('chart-loading'))e.classList.add('hidden')};
const Store={like:[],share:[],comment:[],hashtag:[]};const Pag={like:1,share:1,comment:1,hashtag:1};let allPostsRaw=[];
const Charts={};function makeChart(id,opts){if(Charts[id]){try{Charts[id].destroy()}catch(e){}}const el=_$(id);if(!el)return null;Charts[id]=new ApexCharts(el,opts);Charts[id].render();el.style.display='block';return Charts[id]}window.addEventListener('resize',()=>Object.values(Charts).forEach(c=>{try{c.updateOptions({})}catch(e){}}));
/* ── TABS ── */
const OVTab={_loaded:{hashtag:false,like:false,share:false,comment:false},show(t){TAB_TYPES.forEach(x=>{_$('tab-'+x)?.classList.toggle('active',x===t);_$('panel-'+x)?.classList.toggle('active',x===t)});if(!this._loaded[t]){this._loaded[t]=true;OVData.loadTab(t)}else if(t!=='hashtag'&&Store[t].length)OVData._renderDonut(t,Store[t]);if(t!=='hashtag')setTimeout(()=>{_$('ovTabsBar')?.scrollIntoView({behavior:'smooth',block:'nearest'})},80)},reset(){this._loaded={hashtag:false,like:false,share:false,comment:false}}};
/* ── DATA ── */
const OVData={
    async loadTab(t){if(!OVCfg.pid){this._noProject(t);return}if(t==='hashtag'){await this.loadHashtags();return}await this.loadEngagement(t)},
    async loadHashtags(){const ld=_$('hashtagLoading'),ct=_$('hashtagContent'),em=_$('hashtagEmpty'),bd=_$('badgeHashtag');try{const r=await fetch(`${API_BASE}/trending-topics?project_id=${OVCfg.pid}&start_date=${OVCfg.sd}&end_date=${OVCfg.ed}`);const j=await r.json();if(j.success&&j.data?.hashtags?.length){Store.hashtag=j.data.hashtags;Pag.hashtag=1;if(bd)bd.textContent=j.data.total_hashtags+' hashtags';const ch=_$('chip-hashtag');if(ch)ch.textContent=j.data.total_hashtags;this._renderHashtagList(j.data.hashtags);this._renderDonutHashtag(j.data.hashtags)}else{if(ld)ld.style.display='none';if(em)em.style.display='flex';if(bd)bd.textContent='0'}}catch(e){console.error('[OV]',e);if(ld)ld.style.display='none';if(em)em.style.display='flex';if(bd)bd.textContent='Error'}},
    _renderHashtagList(hashtags){const ld=_$('hashtagLoading'),ct=_$('hashtagContent'),list=_$('hashtagList'),pg=_$('pag-hashtag');if(!list)return;const all=hashtags.slice(0,50);Store.hashtag=all;const page=Pag.hashtag||1,pp=OVCfg.perPage,total=all.length,pages=Math.ceil(total/pp),start=(page-1)*pp,items=all.slice(start,start+pp),mx=all[0]?.size||1;list.innerHTML='';items.forEach((h,i)=>{const rk=start+i+1,rc=rk<=3?` ht-rank--${rk}`:'',pct=Math.round((h.size/mx)*100);const el=document.createElement('div');el.className='ht-item';el.innerHTML=`<div class="ht-rank${rc}">${rk}</div><div class="ht-name">#${esc(h.name)}</div><div class="ht-bar-wrap"><div class="ht-bar-fill" style="width:${pct}%;"></div></div><div class="ht-count">${numF(h.size)}</div>`;el.onclick=()=>this._openHashtagPanel(h);list.appendChild(el)});if(pg){if(pages<=1)pg.innerHTML='';else{const fr=start+1,to=Math.min(start+pp,total);let b='',r=2;b+=`<button class="tme-pag-btn" ${page<=1?'disabled':''} onclick="OVData.goHashtagPage(${page-1})"><i class="ph ph-caret-left"></i></button>`;for(let i=1;i<=pages;i++){if(i===1||i===pages||(i>=page-r&&i<=page+r))b+=`<button class="tme-pag-btn${i===page?' is-active':''}" onclick="OVData.goHashtagPage(${i})">${i}</button>`;else if(i===page-r-1||i===page+r+1)b+=`<span class="tme-pag-btn" style="cursor:default;opacity:.4;">…</span>`}b+=`<button class="tme-pag-btn" ${page>=pages?'disabled':''} onclick="OVData.goHashtagPage(${page+1})"><i class="ph ph-caret-right"></i></button>`;pg.innerHTML=`<div class="tme-pagination"><span class="tme-pag-info">Menampilkan ${fr}–${to} dari ${total} hashtags</span><div class="tme-pag-controls">${b}</div></div>`}}if(ld)ld.style.display='none';if(ct)ct.style.display='block'},
    goHashtagPage(p){Pag.hashtag=p;this._renderHashtagList(Store.hashtag);_$('hashtagList')?.scrollIntoView({behavior:'smooth',block:'nearest'})},
    _renderDonutHashtag(h){const ld=_$('loadingDonutHashtag'),ch=_$('donutHashtagChart');if(!ld||!ch||!h.length){hideLd('loadingDonutHashtag');return}this._renderDonutEcharts(ch,ld,_$('donutHashtagLegend'),h.slice(0,5),'mentions',x=>x.name,x=>x.size,x=>this._openHashtagPanel(x),'Hashtag')},
    async loadEngagement(type){const subMap={like:'fblike',share:'fbshare',comment:'fbcomment'};const rows=parseInt(_$('rows-'+type)?.value||'100');const ls=_$('list-'+type);if(ls)ls.innerHTML=`<div class="spinner-state"><div class="spin-ring"></div>Memuat data…</div>`;try{const r=await fetch(`${API_BASE}/most-engagement?project_id=${OVCfg.pid}&start_date=${OVCfg.sd}&end_date=${OVCfg.ed}&sub=${subMap[type]}&rows=${rows}`);const j=await r.json();let items=j.data||j||[];if(!Array.isArray(items))items=[];Store[type]=items;Pag[type]=1;const ch=_$('chip-'+type);if(ch)ch.textContent=items.length;const bd=_$('badge-'+type);if(bd)bd.textContent=items.length+' posts';if(type==='like'&&!allPostsRaw.length)allPostsRaw=items;if(type==='like')this._updateKpi(items);this._renderList(type);this._renderDonut(type,items)}catch(e){console.error('[OV]',e);if(ls)ls.innerHTML=`<div class="chart-empty" style="padding:40px;"><i class="ph ph-warning"></i><span>Gagal memuat: ${esc(e.message)}</span></div>`;hideLd('loadingDonut-'+type)}},
    _updateKpi(items){let tl=0,ts=0,tc=0;items.forEach(i=>{tl+=parseInt(i.likes||i.num_likes||i.freq||0);ts+=parseInt(i.shares||i.num_shares||0);tc+=parseInt(i.comments||i.num_comments||0)});const n=items.length,av=v=>n?Math.round(v/n):0;const el=(id,v)=>{const e=_$(id);if(e)e.textContent=numF(v)};const sub=(id,v)=>{const e=_$(id);if(e)e.innerHTML=`<i class="ph ph-chart-line-up me-1"></i>Avg ${numF(av(v))} / post &middot; ${n} posts`};el('kpiLikes',tl);sub('kpiLikesSub',tl);el('kpiShares',ts);sub('kpiSharesSub',ts);el('kpiComments',tc);sub('kpiCommentsSub',tc);el('kpiEng',tl+ts+tc);const eS=_$('kpiEngSub');if(eS)eS.innerHTML=`<i class="ph ph-chart-bar me-1"></i>Likes+Shares+Comments &middot; ${n} posts`},
    reloadTab(t){Store[t]=[];Pag[t]=1;this.loadEngagement(t)},
    _noProject(t){const ls=_$('list-'+t);if(ls)ls.innerHTML=`<div class="chart-empty" style="padding:40px;"><i class="ph ph-folder-open"></i><span>Pilih project terlebih dahulu</span></div>`;hideLd('loadingDonut-'+t)},
    _metric(item,type){const k={like:['likes','num_likes','freq'],share:['shares','num_shares'],comment:['comments','num_comments']};return(k[type]||['likes']).reduce((v,f)=>v||parseInt(item[f]||0),0)},
    _getName(item){const n=(item.name||item.author_scr_name||item.author_name||'').replace(/<[^>]*>/g,'').replace(/<b>.*?<\/b>\s*/g,'').trim();return n||'Facebook User'},
    _getAvatar(item){return(item.avatar_url||item.profile_url||item.author_avatar||item.author_image||'').trim()},
    _getColor(item){const seed=item.sub_id||item.id||this._getName(item)||'fb';const pal=['#1877f2','#038047','#273B4A','#F59E0B','#06B6D4','#8b5cf6','#ec4899','#f97316'];let h=0;for(let i=0;i<seed.length;i++)h=(h*31+seed.charCodeAt(i))&0xffffffff;return pal[Math.abs(h)%pal.length]},
    _avHtml(item){const av=this._getAvatar(item),d='/assets/images/user/dummy.jpg';return(av&&av.startsWith('http'))?`<img src="${esc(av)}" onerror="this.src='${d}'">`:`<img src="${d}">`},
    _normSent(item){const r=String(item.sentiment_str||item.sentiment||'').toLowerCase();return r.includes('pos')?'pos':r.includes('neg')?'neg':'neu'},
    _renderList(type){const items=Store[type],ls=_$('list-'+type),pg=_$('pag-'+type);if(!ls)return;if(!items.length){ls.innerHTML=`<div class="chart-empty" style="padding:40px;"><i class="ph ph-folder-open"></i><span>Tidak ada data untuk periode ini</span></div>`;if(pg)pg.innerHTML='';return}const page=Pag[type]||1,total=items.length,pp=OVCfg.perPage,pages=Math.ceil(total/pp),start=(page-1)*pp;ls.innerHTML=`<div class="tme-post-list">${items.slice(start,start+pp).map((it,i)=>this._postHtml(it,start+i,type)).join('')}</div>`;if(pg)pg.innerHTML=this._pagHtml(type,page,pages,total,start+1,Math.min(start+pp,total));ls.querySelectorAll('.tme-post').forEach(el=>{el.addEventListener('click',()=>{try{const it=JSON.parse(decodeURIComponent(el.dataset.item));const lm={like:'Most Liked',share:'Most Shared',comment:'Most Comments'};OVPanel.open(items,type,PLAT+' — '+lm[type]);OVDetail.open(it,type)}catch(e){console.warn(e)}})})},
    _pagHtml(type,page,pages,total,from,to){if(pages<=1)return '';let b='',r=2;b+=`<button class="tme-pag-btn" ${page<=1?'disabled':''} onclick="OVData.goPage('${type}',${page-1})"><i class="ph ph-caret-left"></i></button>`;for(let i=1;i<=pages;i++){if(i===1||i===pages||(i>=page-r&&i<=page+r))b+=`<button class="tme-pag-btn${i===page?' is-active':''}" onclick="OVData.goPage('${type}',${i})">${i}</button>`;else if(i===page-r-1||i===page+r+1)b+=`<span class="tme-pag-btn" style="cursor:default;opacity:.4;">…</span>`}b+=`<button class="tme-pag-btn" ${page>=pages?'disabled':''} onclick="OVData.goPage('${type}',${page+1})"><i class="ph ph-caret-right"></i></button>`;return `<div class="tme-pagination"><span class="tme-pag-info">Menampilkan ${from}–${to} dari ${total} posts</span><div class="tme-pag-controls">${b}</div></div>`},
    goPage(t,p){Pag[t]=p;this._renderList(t);_$('list-'+t)?.scrollIntoView({behavior:'smooth',block:'nearest'})},
    _postHtml(item,gi,type){const rank=gi+1,rkC=rank<=3?'--'+rank:'',name=this._getName(item),color=this._getColor(item),avH=this._avHtml(item),sent=this._normSent(item);const content=dec((item.content||item.name||'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim()).slice(0,200);const dt=(item.date_created||'').split('T')[0],url=item.url||item.link||'';const l=parseInt(item.likes||item.num_likes||item.freq||0),s=parseInt(item.shares||item.num_shares||0),c=parseInt(item.comments||item.num_comments||0),total=l+s+c;const sL={pos:'Positive',neg:'Negative',neu:'Neutral'}[sent],enc=encodeURIComponent(JSON.stringify(item));const lC=type==='like'?' tme-metric--primary':'',sC=type==='share'?' tme-metric--cyan':'',cC=type==='comment'?' tme-metric--amber':'';return `<div class="tme-post" data-item="${esc(enc)}"><div class="tme-post-rank tme-post-rank${rkC}">${rank}</div><div class="tme-post-av" style="background:linear-gradient(135deg,${color},${color}99);">${avH}</div><div class="tme-post-body"><div class="tme-post-author">${esc(name)}</div>${dt?`<div class="tme-post-date">${dt}</div>`:''}${content?`<div class="tme-post-text">${esc(content)}</div>`:''}<div class="tme-post-stats"><span class="tme-metric${lC}"><i class="ph ph-thumbs-up me-1"></i>${numF(l)}</span><span class="tme-metric${sC}"><i class="ph ph-share-network me-1"></i>${numF(s)}</span><span class="tme-metric${cC}"><i class="ph ph-chat-circle me-1"></i>${numF(c)}</span><span class="tme-metric" style="font-weight:800;">∑ ${numF(total)}</span><span class="tme-sent tme-sent--${sent}">${sL}</span>${url?`<a href="${esc(url)}" target="_blank" rel="noopener" class="tme-view-link" onclick="event.stopPropagation()"><i class="ph ph-arrow-square-out me-1"></i>Lihat</a>`:''}</div></div></div>`},
    _renderDonut(type,items){const ld=_$('loadingDonut-'+type),ch=_$('donutChart-'+type),em=_$('donutEmpty-'+type),lg=_$('donutLegend-'+type);if(!ld||!ch)return;if(!items.length){ld.style.display='none';if(em)em.style.display='flex';return}const top5=items.slice(0,5),ml={like:'Likes',share:'Shares',comment:'Comments'}[type];this._renderDonutEcharts(ch,ld,lg,top5,ml,it=>this._getName(it),it=>this._metric(it,type),it=>{OVPanel.open(Store[type],type,PLAT);OVDetail.open(it,type)},ml,it=>dec((it.content||it.name||'').replace(/<[^>]*>/g,'').replace(/\s+/g,' ').trim()))},
    _renderDonutEcharts(chartEl,loadEl,legEl,data,metricLabel,getNameFn,getValFn,onClickFn,titleLabel,getDescFn){if(!chartEl||!data.length){if(loadEl)loadEl.style.display='none';return}const total=data.reduce((s,d)=>s+getValFn(d),0);if(legEl)legEl.innerHTML=data.map((d,i)=>{const n=getNameFn(d),sn=n.length>22?n.slice(0,21)+'…':n;return `<div class="donut-leg-item"><span class="donut-dot" style="background:${DONUT_COLORS[i]};"></span>${sn} · ${numF(getValFn(d))}</div>`}).join('');if(loadEl)loadEl.style.display='none';chartEl.style.display='block';const ek='__ec_'+chartEl.id;if(window[ek]){try{window[ek].dispose()}catch(e){}}if(typeof echarts==='undefined'){chartEl.innerHTML='<div class="chart-empty"><i class="ph ph-chart-donut"></i><span>ECharts not loaded</span></div>';return}const chart=echarts.init(chartEl,null,{renderer:'canvas'});window[ek]=chart;window.addEventListener('resize',()=>{try{chart.resize()}catch(e){}});const pd=data.map((d,i)=>({name:getNameFn(d),value:getValFn(d),_desc:getDescFn?getDescFn(d):'',itemStyle:{color:DONUT_COLORS[i]}}));chart.setOption({backgroundColor:'transparent',animation:true,animationDuration:1000,animationEasing:'cubicOut',animationDelay:idx=>idx*80,tooltip:{show:false},series:[{type:'pie',radius:['38%','62%'],center:['50%','50%'],avoidLabelOverlap:true,selectedMode:false,minAngle:8,itemStyle:{borderColor:'#fff',borderWidth:3},label:{show:true,position:'outside',alignTo:'edge',edgeDistance:20,lineHeight:18,fontSize:11,fontFamily:'inherit',color:'#334155',fontWeight:'500',formatter:p=>{const d=data[p.dataIndex],desc=getDescFn?getDescFn(d).slice(0,80):'',words=desc?desc.split(' '):[],lines=[];let cur='';words.forEach(w=>{if((cur+' '+w).trim().length>40){lines.push(cur.trim());cur=w}else cur=(cur+' '+w).trim()});if(cur)lines.push(cur);const body=lines.join('\n');return `{title|${p.name}}\n${body?body+'\n':''}({val|${numF(p.value)}} ${metricLabel}, {pct|${p.percent.toFixed(1)}%})`},rich:{title:{fontSize:11,fontWeight:'700',color:'#1e293b',lineHeight:18},val:{fontSize:11,fontWeight:'700',color:'#038047'},pct:{fontSize:11,fontWeight:'600',color:'#64748b'}}},labelLine:{show:true,length:18,length2:24,smooth:0.3,lineStyle:{width:1.5,color:'#94A3B8'}},emphasis:{scale:false,itemStyle:{shadowBlur:0,shadowColor:'transparent',borderWidth:3,borderColor:'#fff',opacity:1},labelLine:{lineStyle:{width:2.5,color:'#273B4A'}},label:{show:true}},select:{disabled:true},data:pd}],graphic:[{type:'text',left:'center',top:'46%',z:100,style:{text:numK(total),fill:'#0f172a',font:"800 28px inherit",textAlign:'center'}},{type:'text',left:'center',top:'54%',z:100,style:{text:'TOTAL '+titleLabel.toUpperCase(),fill:'#94a3b8',font:"600 9px inherit",textAlign:'center'}}]});chart.on('click',p=>{const d=data[p.dataIndex];if(d&&onClickFn)onClickFn(d)});let _tt=document.getElementById('ovCustomTT');if(!_tt){_tt=document.createElement('div');_tt.id='ovCustomTT';_tt.style.cssText='position:fixed;z-index:9999;pointer-events:none;background:#1e293b;color:#fff;border:1px solid #334155;border-radius:6px;padding:10px 14px;max-width:280px;font-size:12px;line-height:1.5;display:none;box-shadow:0 8px 24px rgba(0,0,0,.32);font-family:inherit;opacity:0;transform:translateY(6px) scale(.97);transition:opacity .18s ease,transform .18s ease;';document.body.appendChild(_tt)}let _tm=null;chart.on('mouseover',p=>{if(p.componentType!=='series')return;const d=data[p.dataIndex],cl=DONUT_COLORS[p.dataIndex],desc=(getDescFn?getDescFn(d):'').slice(0,160);clearTimeout(_tm);_tt.innerHTML=`<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;"><span style="width:9px;height:9px;border-radius:50%;background:${cl};flex-shrink:0;display:inline-block;"></span><b style="font-size:12.5px;">${esc(p.name)}</b></div>${desc?`<div style="font-size:11px;color:#94a3b8;margin-bottom:6px;">${esc(desc)}</div>`:''}<div style="display:flex;align-items:center;gap:8px;"><b style="font-size:13px;">${numF(p.value)} ${metricLabel}</b><span style="color:${cl};font-weight:700;">${p.percent.toFixed(1)}%</span></div>`;_tt.style.display='block';requestAnimationFrame(()=>{_tt.style.opacity='1';_tt.style.transform='translateY(0) scale(1)'})});chart.on('mouseout',()=>{_tt.style.opacity='0';_tt.style.transform='translateY(6px) scale(.97)';_tm=setTimeout(()=>{_tt.style.display='none'},180)});chartEl.addEventListener('mousemove',e=>{if(_tt.style.display==='none')return;const vw=window.innerWidth,vh=window.innerHeight,tw=_tt.offsetWidth+16,th=_tt.offsetHeight+16;let x=e.clientX+18,y=e.clientY-10;if(x+tw>vw)x=e.clientX-tw;if(y+th>vh)y=e.clientY-th;_tt.style.left=x+'px';_tt.style.top=y+'px'})},
    _openHashtagPanel(h){const tag='#'+h.name.toLowerCase();const filtered=allPostsRaw.filter(p=>(p.content||p.name||'').toLowerCase().includes(tag));OVPanel.open(filtered.length?filtered:allPostsRaw.slice(0,20),'like',`${PLAT} — #${h.name} (${h.size} mentions)`)},
    exportCsv(type){const items=Store[type];if(!items?.length){alert('Tidak ada data.');return}const hdr='index;nama;sentiment;likes;shares;comments;total;tanggal;url;konten';const rows=items.map((it,i)=>{const nm=this._getName(it),sn=this._normSent(it),sl={pos:'Positif',neg:'Negatif',neu:'Netral'}[sn],l=parseInt(it.likes||it.freq||0),s=parseInt(it.shares||0),c=parseInt(it.comments||0),ct=(it.content||it.name||'').replace(/<[^>]*>/g,'').trim().slice(0,300).replace(/;/g,',').replace(/\n/g,' ');return `${i};${nm.replace(/;/g,',')};${sl};${l};${s};${c};${l+s+c};${(it.date_created||'').split('T')[0]};${it.url||''};${ct}`});const blob=new Blob(['\uFEFF'+[hdr,...rows].join('\r\n')],{type:'text/csv;charset=utf-8;'});Object.assign(document.createElement('a'),{href:URL.createObjectURL(blob),download:`Facebook_${type}_${OVCfg.sd}_${OVCfg.ed}.csv`}).click()},
};
/* ── PANEL ── */
const OVPanel={_items:[],_type:null,open(items,type,title){this._items=items||[];this._type=type;OVDetail.close();_$('ovPanelDot').style.background=OVCfg.colors[type]||OVCfg.primary;_$('ovPanelTitle').textContent=title||PLAT+' Posts';_$('ovPanelMeta').textContent=OVCfg.sd+' – '+OVCfg.ed;const ov=_$('ovPanelOverlay'),pn=_$('ovSntPanel');ov.classList.remove('hiding');pn.classList.remove('hiding');ov.classList.add('show');pn.classList.add('show');this._render(items,type)},close(){OVDetail.close();const ov=_$('ovPanelOverlay'),pn=_$('ovSntPanel');pn.classList.add('hiding');ov.classList.add('hiding');setTimeout(()=>{pn.classList.remove('show','hiding');ov.classList.remove('show','hiding')},240)},exportCsv(){OVData.exportCsv(this._type||'like')},_render(items,type){const list=_$('ovPanelList');if(!list)return;if(!items?.length){list.innerHTML='<div class="do-panel-loading"><div class="do-panel-spinner"></div>Tidak ada data</div>';return}const ml={like:'Likes',share:'Shares',comment:'Komentar'}[type]||'Likes';list.innerHTML=items.slice(0,100).map(item=>{const nm=OVData._getName(item),av=OVData._getAvatar(item),cl=OVData._getColor(item),d='/assets/images/user/dummy.jpg',aH=(av&&av.startsWith('http'))?`<img src="${esc(av)}" onerror="this.src='${d}'">`:`<img src="${d}">`,tx=(item.content||item.name||'').replace(/<[^>]*>/g,'').trim(),mv=OVData._metric(item,type),dt=(item.date_created||'').split('T')[0],sn=OVData._normSent(item),sl={pos:'Pos',neg:'Neg',neu:'Neu'}[sn],l=parseInt(item.likes||item.freq||0),s=parseInt(item.shares||0),c=parseInt(item.comments||0),total=l+s+c,enc=encodeURIComponent(JSON.stringify(item));return `<div class="do-panel-item" data-item="${esc(enc)}" data-type="${type}" onclick="OVPanel._click(this)"><div class="do-panel-avatar" style="background:linear-gradient(135deg,${cl},${cl}99);">${aH}</div><div class="do-panel-item-body"><div class="do-panel-author">${esc(nm)}</div><div class="do-panel-text">${esc(dec(tx).slice(0,130)||'(tidak ada konten)')}</div><div class="do-panel-footer"><span class="do-sent-badge do-sent-badge--${sn}">${sl}</span><span>${ml} ${numF(mv)}</span><span>∑ ${numF(total)}</span>${dt?`<span style="margin-left:auto;">${dt}</span>`:''}</div></div></div>`}).join('');if(items.length>100)list.insertAdjacentHTML('beforeend',`<div style="padding:8px;text-align:center;font-size:10px;font-weight:600;color:#94A3B8;background:var(--slate-50);border-top:1px dashed var(--slate-200);">+${(items.length-100).toLocaleString()} lainnya</div>`)},_click(el){try{const item=JSON.parse(decodeURIComponent(el.dataset.item.replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"')));OVDetail.open(item,el.dataset.type||this._type)}catch(e){console.warn(e)}}};
/* ── DETAIL ── */
const OVDetail={open(item,type){const panel=_$('ovDetailPanel'),body=_$('ovDetailBody'),title=_$('ovDetailTitle');if(!panel||!body)return;const color=OVCfg.colors[type]||OVCfg.primary,name=OVData._getName(item),av=OVData._getAvatar(item),ac=OVData._getColor(item),d='/assets/images/user/dummy.jpg',aH=(av&&av.startsWith('http'))?`<img src="${esc(av)}" onerror="this.src='${d}'">`:`<img src="${d}">`;const raw=(item.content||item.name||'').replace(/<[^>]*>/g,'').trim(),ct=raw?dec(raw):'',url=item.url||item.link||'',dt=item.date_created||'';const l=parseInt(item.likes||item.num_likes||item.freq||0),s=parseInt(item.shares||item.num_shares||0),c=parseInt(item.comments||item.num_comments||0);const sn=OVData._normSent(item),sl={pos:'Positif',neg:'Negatif',neu:'Netral'}[sn];let dtF='';if(dt)try{dtF=new Date(dt).toLocaleDateString('id-ID',{weekday:'long',day:'2-digit',month:'long',year:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){dtF=dt.split('T')[0]}title.textContent=name;body.innerHTML=`<div class="do-dp2-avatar-row"><div class="do-dp2-avatar-lg" style="background:linear-gradient(135deg,${ac},${ac}99);">${aH}</div><div><div class="do-dp2-name">${esc(name)}</div><span class="do-dp2-plat-badge" style="background:#1877f218;color:#1877f2;">Facebook</span></div></div>${dtF?`<div class="do-dp2-meta">${dtF}</div>`:''}<div class="do-dp2-sent do-dp2-sent--${sn}">${sl}</div>${ct?`<div class="do-dp2-content">${esc(ct)}</div>`:''}<div class="do-dp2-stats"><div class="do-dp2-stat"><div class="do-dp2-stat-val">${numF(l)}</div><div class="do-dp2-stat-lbl">Likes</div></div><div class="do-dp2-stat"><div class="do-dp2-stat-val">${numF(s)}</div><div class="do-dp2-stat-lbl">Shares</div></div><div class="do-dp2-stat"><div class="do-dp2-stat-val">${numF(c)}</div><div class="do-dp2-stat-lbl">Comments</div></div></div>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="do-dp2-link"><i class="ph ph-arrow-square-out me-1"></i>Buka di Facebook</a>`:''}`;panel.classList.add('show')},close(){_$('ovDetailPanel')?.classList.remove('show')}};
/* ── INIT ── */
document.addEventListener('DOMContentLoaded',()=>{if(!OVCfg.pid)return;OVTab._loaded.hashtag=true;OVData.loadHashtags();OVData.loadEngagement('like').then(()=>{OVTab._loaded.like=true});document.addEventListener('keydown',e=>{if(e.key==='Escape')OVPanel.close()})});
</script>
